#include <vector>
#include <queue>

using namespace std;

class Solution {
public:
    vector<int> baseUnitConversions(vector<vector<int>>& conversions) {
        constexpr int MOD = 1'000'000'007;
        int n = conversions.size() + 1;
        vector<int> ans(n, 0);
        ans[0] = 1;
        vector<vector<pair<int, int>>> graph(n);
        for (const auto& c : conversions) {
            graph[c[0]].push_back({c[1], c[2]});
        }
        queue<int> q;
        q.push(0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (const auto& [v, factor] : graph[u]) {
                ans[v] = ((long long)ans[u] * factor) % MOD;
                q.push(v);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] baseUnitConversions(int[][] conversions) {
        int MOD = 1_000_000_007;
        int n = conversions.length + 1;
        int[] ans = new int[n];
        ans[0] = 1;
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] c : conversions) {
            graph[c[0]].add(new int[]{c[1], c[2]});
        }
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(0);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int[] edge : graph[u]) {
                int v = edge[0], factor = edge[1];
                ans[v] = (int) (((long) ans[u] * factor) % MOD);
                q.add(v);
            }
        }
        return ans;
    }
}

var baseUnitConversions = function(conversions) {
    const MOD = 1000000007n;
    const n = conversions.length + 1;
    const ans = new Array(n).fill(0n);
    ans[0] = 1n;
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v, factor] of conversions) {
        graph[u].push([v, BigInt(factor)]);
    }
    const q = [0];
    while (q.length > 0) {
        const u = q.shift();
        for (const [v, factor] of graph[u]) {
            ans[v] = (ans[u] * factor) % MOD;
            q.push(v);
        }
    }
    return ans.map(x => Number(x));
};
